// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.17;

import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable-4.9.6/access/OwnableUpgradeable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable-4.9.6/proxy/utils/UUPSUpgradeable.sol";

import {TreasuryManagement} from "./TreasuryManagement.sol";
import {PortfolioSettings, AssetManagerCheck} from "./PortfolioSettings.sol";
import {TokenWhitelistManagement} from "./TokenWhitelistManagement.sol";
import {UserWhitelistManagement} from "./UserWhitelistManagement.sol";
import {FeeManagement} from "./FeeManagement.sol";

import {FunctionParameters} from "../../FunctionParameters.sol";

import {AccessRoles} from "../../access/AccessRoles.sol";

import {IAccessController} from "../../access/IAccessController.sol";

/**
 * @title MainContract
 * @dev Main contract integrating all management functionalities with access control.
 */
contract AssetManagementConfig is
  OwnableUpgradeable,
  UUPSUpgradeable,
  TreasuryManagement,
  PortfolioSettings,
  TokenWhitelistManagement,
  FeeManagement,
  UserWhitelistManagement,
  AccessRoles
{
  IAccessController internal accessController;

  /// @custom:oz-upgrades-unsafe-allow constructor
  constructor() {
    _disableInitializers();
  }

  // Implement the OwnableUpgradeable initialization.
  function init(
    FunctionParameters.AssetManagementConfigInitData calldata initData
  ) external initializer {
    __Ownable_init();
    __UUPSUpgradeable_init();

    accessController = IAccessController(initData._accessController);

    // init parents
    __TreasuryManagement_init(initData._assetManagerTreasury);

    __PortfolioSettings_init(
      initData._protocolConfig,
      initData._initialPortfolioAmount,
      initData._minPortfolioTokenHoldingAmount,
      initData._publicPortfolio,
      initData._transferable,
      initData._transferableToPublic
    );

    __TokenWhitelistManagement_init(
      initData._whitelistedTokens,
      initData._whitelistTokens,
      initData._protocolConfig
    );

    __FeeManagement_init(
      initData._protocolConfig,
      initData._managementFee,
      initData._performanceFee,
      initData._entryFee,
      initData._exitFee,
      initData._feeModule
    );

    __UserWhitelistManagement_init(initData._protocolConfig);
  }

  // Override the onlyOwner modifier to specify it overrides from OwnableUpgradeable.
  function _isAssetManager()
    internal
    view
    override(AssetManagerCheck)
    returns (bool)
  {
    return accessController.hasRole(ASSET_MANAGER, msg.sender);
  }

  // Override the onlyOwner modifier to specify it overrides from OwnableUpgradeable.
  function _isWhitelistManager()
    internal
    view
    override(AssetManagerCheck)
    returns (bool)
  {
    return accessController.hasRole(WHITELIST_MANAGER, msg.sender);
  }

  /**
   * @notice Authorizes upgrade for this contract
   * @param newImplementation Address of the new implementation
   */
  function _authorizeUpgrade(
    address newImplementation
  ) internal override onlyOwner {
    // Intentionally left empty as required by an abstract contract
  }
}

contracts/config/assetManagement/UserWhi.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.17;

import {ErrorLibrary} from "../../library/ErrorLibrary.sol";
import {AssetManagerCheck} from "./AssetManagerCheck.sol";
import {IProtocolConfig} from "../../config/protocol/IProtocolConfig.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable-4.9.6/proxy/utils/Initializable.sol";

/**
 * @title UserWhitelistManagement
 * @dev Manages user whitelisting, allowing for flexible access control.
 */
abstract contract UserWhitelistManagement is AssetManagerCheck, Initializable {
  // Reference to the protocol configuration contract
  IProtocolConfig private protocolConfig;

  mapping(address => bool) public whitelistedUsers;

  event UserWhitelisted(address[] users);
  event UserRemovedFromWhitelist(address[] users);

  function __UserWhitelistManagement_init(
    address _protocolConfig
  ) internal onlyInitializing {
    if (_protocolConfig == address(0)) revert ErrorLibrary.InvalidAddress();
    protocolConfig = IProtocolConfig(_protocolConfig);
  }

  /**
   * @notice This function whitelists users which can deposit in a particular portfolio
   * @param users Array of user addresses to be whitelisted by the asset manager
   */
  function whitelistUser(
    address[] calldata users
  ) external virtual onlyWhitelistManager {
    uint256 len = users.length;
    if (len > protocolConfig.whitelistLimit())
      revert ErrorLibrary.InvalidWhitelistLimit();
    for (uint256 i; i < len; i++) {
      address _user = users[i];
      if (_user == address(0)) revert ErrorLibrary.InvalidAddress();
      whitelistedUsers[_user] = true;
    }
    emit UserWhitelisted(users);
  }

  /**
   * @notice This function removes a previously whitelisted user
   * @param users Array of user addresses to be removed from whiteist by the asset manager
   */
  function removeWhitelistedUser(
    address[] calldata users
  ) external virtual onlyWhitelistManager {
    uint256 len = users.length;
    for (uint256 i; i < len; i++) {
      if (users[i] == address(0)) revert ErrorLibrary.InvalidAddress();
      whitelistedUsers[users[i]] = false;
    }
    emit UserRemovedFromWhitelist(users);
  }
}

contracts/config/assetManagement/TokenWh.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.17;

import {ErrorLibrary} from "../../library/ErrorLibrary.sol";
import {AssetManagerCheck} from "./AssetManagerCheck.sol";
import {IProtocolConfig} from "../../config/protocol/IProtocolConfig.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable-4.9.6/proxy/utils/Initializable.sol";

/**
 * @title TokenWhitelistManagement
 * @dev Manages the whitelisting of tokens, determining which tokens are authorized for use within the system.
 * This enables control over the tokens that can participate in the platform, enhancing security and compliance.
 */
abstract contract TokenWhitelistManagement is AssetManagerCheck, Initializable {
  // Reference to the protocol configuration contract
  IProtocolConfig private protocolConfig;

  // Mapping to track whitelisted tokens.
  mapping(address => bool) public whitelistedTokens;

  // Flag to indicate if token whitelisting is enabled.
  bool public tokenWhitelistingEnabled;

  // Events for logging changes to the whitelist.
  event TokenWhitelisted(address[] tokens);
  event TokensRemovedFromWhitelist(address[] tokens);

  /**
   * @dev Initializes the contract with a list of tokens to be whitelisted and sets the whitelisting enabled flag.
   * @param _whitelistTokens Initial list of tokens to whitelist.
   * @param _tokenWhitelistingEnabled Flag indicating if token whitelisting is enabled.
   */
  function __TokenWhitelistManagement_init(
    address[] calldata _whitelistTokens,
    bool _tokenWhitelistingEnabled,
    address _protocolConfig
  ) internal onlyInitializing {
    if (_protocolConfig == address(0)) revert ErrorLibrary.InvalidAddress();
    protocolConfig = IProtocolConfig(_protocolConfig);
    tokenWhitelistingEnabled = _tokenWhitelistingEnabled;
    if (tokenWhitelistingEnabled) {
      if (_whitelistTokens.length == 0)
        revert ErrorLibrary.InvalidTokenWhitelistLength();

      _addTokensToWhitelist(_whitelistTokens);
    }
  }

  /**
   * @dev Internal function to add tokens to the whitelist.
   * @param _tokens Array of token addresses to whitelist.
   */
  function _addTokensToWhitelist(address[] calldata _tokens) internal {
    uint256 tokensLength = _tokens.length;
    if (tokensLength > protocolConfig.whitelistLimit())
      revert ErrorLibrary.InvalidWhitelistLimit();
    for (uint256 i; i < tokensLength; i++) {
      address _token = _tokens[i];
      if (_token == address(0)) {
        revert ErrorLibrary.InvalidAddress();
      }
      whitelistedTokens[_token] = true;
    }
    emit TokenWhitelisted(_tokens);
  }
}

